<script setup lang="ts">
const api=useApi(); const { data: contractors, refresh }=await useAsyncData('admin-contractors',()=>api.request<any[]>('/admin/contractors').catch(()=>[]))
async function setStatus(id:string,status:string){await api.request(`/admin/contractors/${id}/verify`,{method:'POST',body:{status}});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Supply network</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Contractors.</h1><p class="mt-1 text-[11.5px] text-ink/45">License, insurance and capability verification for the repair network.</p></div><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><div v-for="c in contractors" :key="c._id" class="a-card p-5"><div class="flex items-start justify-between"><div><p class="font-display text-[20px]">{{ c.org?.name || 'Contractor' }}</p><p class="font-mono text-[8px] text-ink/30">{{ c.licenseNumber || 'No license on file' }}</p></div><StatusPill :status="c.verificationStatus"/></div><div class="mt-4 grid grid-cols-2 gap-2 border-t border-ink/10 pt-3 text-[10.5px]"><div><p class="font-mono text-[7px] uppercase text-ink/30">Insurance</p><p>{{ c.insuranceProvider || '—' }}</p></div><div><p class="font-mono text-[7px] uppercase text-ink/30">Expiry</p><p>{{ shortDate(c.insuranceExpiry) }}</p></div><div><p class="font-mono text-[7px] uppercase text-ink/30">Areas</p><p>{{ (c.serviceAreas || []).join(', ') || '—' }}</p></div><div><p class="font-mono text-[7px] uppercase text-ink/30">Completed</p><p>{{ c.completedJobs }} jobs · {{ c.rating }}/5</p></div></div><div class="mt-3 flex gap-2"><button v-if="c.verificationStatus!=='verified'" class="btn btn-dark !min-h-8 !text-[9px]" @click="setStatus(c._id,'verified')">Verify</button><button v-else class="font-mono text-[8px] uppercase text-signal-deep" @click="setStatus(c._id,'suspended')">Suspend</button></div></div></div></div></template>
